+template <typename CubeBlockType, typename VecBlockType>
+__aicore__ inline void FAKernelNoquantMla<CubeBlockType, VecBlockType>::InitBuffer()
+{
+    if ASCEND_IS_AIV {
+        this->vecBlock.InitLocalBuffer(this->tPipe, constInfo);
+    }
+}
