+            AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(EVENT_ID7);
+            for (uint32_t qNIdx = 0; qNIdx < qNThisSubBlock; qNIdx++) {
+                AscendC::DataCopyPad(
+                    gLse[qNIdx],
+                    lseOutUbTensor,
+                    AscendC::DataCopyExtParams(
+                        qSThisSubBlock, sizeof(ElementLseOut),
